// The Teleport mod's destination list (mod_teleport_dests.c, generated by
// tools/teleport_dests.py from the stage modules' room exits).
#ifndef PORT_MOD_TELEPORT_H
#define PORT_MOD_TELEPORT_H

#include <stdint.h>

// A place the game itself puts Mega Man: a door's arrival point and facing.
typedef struct
{
    uint8_t stage, room; // Game_work +0x50, +0x51
    int16_t x, y, z;     // y is up-negative; doors give one unit above the floor
    int16_t rot;         // facing (0x1000 a turn)
    const char *name;
    const char *warning; // NULL, or why the destination may misbehave
} TP_DEST;

// The destinations of one stage: tp_dests[first .. first + count - 1].
typedef struct
{
    const char *name;
    uint8_t stage;
    int first, count;
} TP_AREA;

extern const TP_DEST tp_dests[];
extern const TP_AREA tp_areas[];
extern const int tp_area_count;

#endif
